#!/usr/bin/env bash
REPORT=/var/log/audit/report.txt
HOST=$(hostname -s)

emit_header() {
    echo "==== audit report for $HOST ===="
    echo "generated: $(date -u '+%Y-%m-%dT%H:%M:%SZ')"
}

summarize() {
    local path=$1
    awk '
        /ERROR/ { errs++ }
        /WARN/  { warns++ }
        END     { printf "errors=%d warnings=%d\n", errs, warns }
    "$path"
}

emit_header > "$REPORT"
for f in /var/log/audit/*.log; do
    echo "--- $f" >> "$REPORT"
    summarize "$f" >> "$REPORT"
done
echo "done: wrote $REPORT"

