#!/usr/bin/env bash
LOGDIR=${LOGDIR:-/var/log/pipeline}
mkdir -p "$LOGDIR"

run_step() {
    local name=$1
    shift
    {
        echo "--- begin $name"
        "$@"
        echo "--- end $name"
    } >>
}

run_step extract   ./bin/extract --src s3://bucket/in
run_step transform ./bin/transform --workers 4
run_step load      ./bin/load --dest postgres://db/app

if grep -q ERROR "$LOGDIR"/*.log; then
    tail -n 50 "$LOGDIR"/*.log >&2
    exit 1
fi

