#!/usr/bin/env bash
usage() {
    cat <<USAGE
usage: ctl {start|stop|status} [name]
USAGE
}

ctl() {
    local action=$1
    local name=${2:-default}
    case $action in
        start)
            systemctl start "$name"
            ;;
        stop)
            systemctl stop "$name"
            ;;
        status)
            systemctl status "$name" --no-pager
            ;;
        *)
            usage
            return 2
            ;;
}

ctl "$@"

#!/usr/bin/env bash
set -Eeuo pipefail

declare -r LOCK=/var/lock/reindex.lock
declare -g STARTED=0

on_err() {
    local line=$1
    local cmd=$2
    printf 'error at line %d: %s\n' "$line" "$cmd" >&2
}

trap 'on_err "$LINENO" "$BASH_COMMAND"' ERR
trap '[[ $STARTED -eq 1 ]] && rm -f -- "$LOCK"' EXIT INT TERM

{
    exec 9>"$LOCK"
    flock -n 9 || { echo 'already running' >&2; exit 75; }
    STARTED=1
} 2>/dev/null

./bin/reindex --full |& tee -a /var/log/reindex.log

echo "exit=${PIPESTATUS[0]:-0}"
